function Trend({rows,metric,unit}:{rows:Row[];metric:string;unit:string}){
 const valid=rows.filter(r=>typeof r[metric]==='number');if(!valid.length)return <Empty>No readings recorded</Empty>;
 const vals=valid.map(r=>r[metric]),lo=Math.min(...vals),hi=Math.max(...vals),pad=(hi-lo)*.25||1,min=lo-pad,max=hi+pad;
 const first=new Date(rows[0].day).getTime(),last=new Date(rows.at(-1)!.day).getTime();const x=(r:Row)=>55+((new Date(r.day).getTime()-first)/(last-first||1))*550,y=(v:number)=>157-(v-min)/(max-min)*126;
 const draw=(sourceRows:Row[])=>{let path='';let gap=true;let previous='';for(const r of sourceRows){if(r[metric]===null||r[metric]===undefined){gap=true;continue;}if(previous&&metric!=='weightKg'&&new Date(r.day).getTime()-new Date(previous).getTime()>86400000)gap=true;path+=(gap?'M':'L')+x(r)+','+y(r[metric])+' ';gap=false;previous=r.day;}return path;};const paths=metric==='weightKg'?[{d:draw(rows.filter(r=>r.origin==='Clinic')),color:'#9b7c18'},{d:draw(rows.filter(r=>r.origin==='Home')),color:'#66877c'}]:[{d:draw(rows),color:'#9b7c18'}];
 return <div className="trend"><svg viewBox="0 0 650 205" role="img" aria-label={`${metric} trend in ${unit}`}><text x="10" y="16">{unit}</text>{[0,1,2].map(i=><g key={i}><line x1="55" x2="610" y1={32+i*62} y2={32+i*62} stroke="#e4e5df"/><text x="7" y={37+i*62}>{(max-(max-min)*i/2).toFixed(metric==='weightKg'?1:0)}</text></g>)}{paths.map((p,i)=><path key={i} d={p.d} fill="none" stroke={p.color} strokeWidth="3"/>)}{valid.map(r=><circle key={r.id||r.day+r.origin} cx={x(r)} cy={y(r[metric])} r="5" fill={r.origin==='Home'?'#fff':'#a48416'} stroke="#a48416" strokeWidth="2"><title>{date(r.day)}: {r[metric]} {unit}{r.origin?' · '+r.origin:''}</title></circle>)}{[rows[0],rows.at(-1)!].map((r,i)=><text key={i} x={i?610:55} y="193" textAnchor={i?'end':'start'}>{date(r.day)}</text>)}</svg></div>;
}
